18:   error.value = ''
19:   const id = String(route.params.id)
20:   const { data, error: apiError } = await api.GET('/api/videos/{video_id}', {
21:     params: { path: { video_id: id } },
22:   })
23:   if (apiError || !data) {
24:     error.value = 'Video not found or unavailable.'
25:     video.value = null
26:   } else {
27:     video.value = data
28:   }
